static int hexbytes(const char *s, u8 *out) {
    int n = 0;
    for (; s[0] && s[1]; s += 2) {
        int v = 0;
        for (int i = 0; i < 2; i++) { char c = s[i]; v = v * 16 + (c <= '9' ? c - '0' : c >= 'a' ? c - 'a' + 10 : c - 'A' + 10); }
        out[n++] = (u8)v;
    }
    return n;
}

// ---- Serpent (Anderson, Biham, Knudsen), bitslice description of sections 3 and 4 ----
#ifndef SERPENT_R13
#define SERPENT_R13 13         // first rotation of the linear transformation
#endif
static u32 rol(u32 x, int n) { return (x << n) | (x >> (32 - n)); }
static u32 ror(u32 x, int n) { return (x >> n) | (x << (32 - n)); }
static u32 K[33][4];
static void sbox_apply(u32 *x, const u8 *sb) {          // 32 parallel copies of a 4-bit S-box; x[0] holds the least significant input bits
    u32 o0 = 0, o1 = 0, o2 = 0, o3 = 0;
    for (int b = 0; b < 32; b++) {
        int in = (int)((x[0] >> b) & 1) | (int)(((x[1] >> b) & 1) << 1) | (int)(((x[2] >> b) & 1) << 2) | (int)(((x[3] >> b) & 1) << 3);
        int out = sb[in];
        o0 |= (u32)(out & 1) << b; o1 |= (u32)((out >> 1) & 1) << b; o2 |= (u32)((out >> 2) & 1) << b; o3 |= (u32)((out >> 3) & 1) << b;
    }
    x[0] = o0; x[1] = o1; x[2] = o2; x[3] = o3;
}
static void lt(u32 *x) {                                // linear transformation (section 3)
    u32 X0 = x[0], X1 = x[1], X2 = x[2], X3 = x[3];
    X0 = rol(X0, SERPENT_R13); X2 = rol(X2, 3);
    X1 = X1 ^ X0 ^ X2; X3 = X3 ^ X2 ^ (X0 << 3);
    X1 = rol(X1, 1); X3 = rol(X3, 7);
    X0 = X0 ^ X1 ^ X3; X2 = X2 ^ X3 ^ (X1 << 7);
    X0 = rol(X0, 5); X2 = rol(X2, 22);
    x[0] = X0; x[1] = X1; x[2] = X2; x[3] = X3;
}
static void lt_inv(u32 *x) {                            // each step of lt undone, in reverse order
    u32 X0 = x[0], X1 = x[1], X2 = x[2], X3 = x[3];
    X2 = ror(X2, 22); X0 = ror(X0, 5);
    X2 = X2 ^ X3 ^ (X1 << 7); X0 = X0 ^ X1 ^ X3;
    X3 = ror(X3, 7); X1 = ror(X1, 1);
    X3 = X3 ^ X2 ^ (X0 << 3); X1 = X1 ^ X0 ^ X2;
    X2 = ror(X2, 3); X0 = ror(X0, SERPENT_R13);
    x[0] = X0; x[1] = X1; x[2] = X2; x[3] = X3;
}
// Keys and blocks are byte strings; bytes 4i..4i+3 form little-endian 32-bit word i (the printed vectors use this byte order, as a
// first-vector check showed; Serpent's bit 0 is the least significant bit of byte 0).
static void to_words(const u8 *p, int nbytes, u32 *w) {
    for (int i = 0; i < nbytes / 4; i++) w[i] = (u32)p[4 * i] | ((u32)p[4 * i + 1] << 8) | ((u32)p[4 * i + 2] << 16) | ((u32)p[4 * i + 3] << 24);
}
static void from_words(const u32 *w, u8 *p) {
    for (int i = 0; i < 4; i++) { p[4 * i] = (u8)w[i]; p[4 * i + 1] = (u8)(w[i] >> 8); p[4 * i + 2] = (u8)(w[i] >> 16); p[4 * i + 3] = (u8)(w[i] >> 24); }
}
static void serpent_key(const u8 *printed, int klen) {  // klen in bytes
    u32 w[140]; u32 kw[8];
    for (int i = 0; i < 8; i++) kw[i] = 0;
    to_words(printed, klen, kw);
    if (klen < 32) kw[klen / 4] |= 1;                     // pad a 1 bit after the key, then zeros (section 2)
    for (int i = 0; i < 8; i++) w[i] = kw[i];             // w[i + 8] is w_i of the paper
    for (int i = 0; i < 132; i++) w[i + 8] = rol(w[i] ^ w[i + 3] ^ w[i + 5] ^ w[i + 7] ^ 0x9e3779b9u ^ (u32)i, 11);
    for (int g = 0; g <= 32; g++) {
        u32 t[4] = {w[8 + 4 * g], w[8 + 4 * g + 1], w[8 + 4 * g + 2], w[8 + 4 * g + 3]};
        sbox_apply(t, SBX[(3 + 8 * 32 - g) & 7]);
        for (int j = 0; j < 4; j++) K[g][j] = t[j];
    }
}
static void serpent_enc(const u8 *in, u8 *out) {
    u32 x[4]; to_words(in, 16, x);
    for (int i = 0; i < 32; i++) {
        for (int j = 0; j < 4; j++) x[j] ^= K[i][j];
        sbox_apply(x, SBX[i & 7]);
        if (i < 31) lt(x); else for (int j = 0; j < 4; j++) x[j] ^= K[32][j];
    }
    from_words(x, out);
}
static void serpent_dec(const u8 *in, u8 *out) {
    u32 x[4]; to_words(in, 16, x);
    for (int i = 31; i >= 0; i--) {
        if (i == 31) for (int j = 0; j < 4; j++) x[j] ^= K[32][j]; else lt_inv(x);
        sbox_apply(x, ISBX[i & 7]);
        for (int j = 0; j < 4; j++) x[j] ^= K[i][j];
    }
    from_words(x, out);
}

static int eq16(const u8 *a, const u8 *b) { for (int i = 0; i < 16; i++) if (a[i] != b[i]) return 0; return 1; }
int paper_main(void) {
    static const int BITS[3] = {128, 192, 256};
    int shown = 0, bad = 0, total_enc = 0, total_dec = 0, ok_enc = 0, ok_dec = 0, iter_ok = 0, iter_n = 0;
    // inverse S-boxes printed in the paper must invert the S-boxes
    int inv_bad = 0; for (int s = 0; s < 8; s++) for (int x = 0; x < 16; x++) if (ISBX[s][SBX[s][x]] != x) inv_bad++;
    pstr("printed inverse S-boxes invert the printed S-boxes: "); pdec(128 - inv_bad); pstr(" of 128 entries\n");
    bad += inv_bad;
    for (int sz = 0; sz < 3; sz++) {
        int klen = BITS[sz] / 8, ne, nd, ni;
        const struct rec *E, *D; const char *(*IT)[4];
        if (sz == 0) { E = ENC128; D = DEC128; IT = ITER128; ne = (int)(sizeof ENC128 / sizeof ENC128[0]); nd = (int)(sizeof DEC128 / sizeof DEC128[0]); ni = (int)(sizeof ITER128 / sizeof ITER128[0]); }
        else if (sz == 1) { E = ENC192; D = DEC192; IT = ITER192; ne = (int)(sizeof ENC192 / sizeof ENC192[0]); nd = (int)(sizeof DEC192 / sizeof DEC192[0]); ni = (int)(sizeof ITER192 / sizeof ITER192[0]); }
        else { E = ENC256; D = DEC256; IT = ITER256; ne = (int)(sizeof ENC256 / sizeof ENC256[0]); nd = (int)(sizeof DEC256 / sizeof DEC256[0]); ni = (int)(sizeof ITER256 / sizeof ITER256[0]); }
        int e_ok = 0, d_ok = 0;
        for (int i = 0; i < ne; i++) {
            u8 key[32], pt[16], want[16], got[16];
            hexbytes(E[i].k, key); hexbytes(E[i].a, pt); hexbytes(E[i].b, want);
            serpent_key(key, klen); serpent_enc(pt, got);
            if (eq16(got, want)) e_ok++; else if (shown++ < 3) pcheck_bytes("encrypt", got, want, 16);
        }
        for (int i = 0; i < nd; i++) {
            u8 key[32], ct[16], want[16], got[16];
            hexbytes(D[i].k, key); hexbytes(D[i].a, ct); hexbytes(D[i].b, want);
            serpent_key(key, klen); serpent_dec(ct, got);
            if (eq16(got, want)) d_ok++; else if (shown++ < 3) pcheck_bytes("decrypt", got, want, 16);
        }
        pstr("Serpent-"); pdec(BITS[sz]); pstr(": encryption vectors "); pdec(e_ok); pstr(" of "); pdec(ne);
        pstr(", decryption vectors "); pdec(d_ok); pstr(" of "); pdec(nd); pstr("\n");
        total_enc += ne; total_dec += nd; ok_enc += e_ok; ok_dec += d_ok;
        for (int i = 0; i < ni; i++) {          // set 4: iterate encryption 100 and 1000 times, feeding the ciphertext back
            u8 key[32], blk[16], w100[16], w1000[16];
            hexbytes(IT[i][0], key); hexbytes(IT[i][1], blk); hexbytes(IT[i][2], w100); hexbytes(IT[i][3], w1000);
            serpent_key(key, klen);
            for (int n = 1; n <= 1000; n++) {
                u8 o[16]; serpent_enc(blk, o); for (int j = 0; j < 16; j++) blk[j] = o[j];
                if (n == 100) { iter_n++; if (eq16(blk, w100)) iter_ok++; else pcheck_bytes("iterated 100", blk, w100, 16); }
            }
            iter_n++; if (eq16(blk, w1000)) iter_ok++; else pcheck_bytes("iterated 1000", blk, w1000, 16);
        }
    }
    pstr("encryption vectors: "); pdec(ok_enc); pstr(" of "); pdec(total_enc); pstr(" match\n");
    pstr("decryption vectors: "); pdec(ok_dec); pstr(" of "); pdec(total_dec); pstr(" match\n");
    pstr("iterated 100 and 1000 times (set 4): "); pdec(iter_ok); pstr(" of "); pdec(iter_n); pstr(" match\n");
    if (ok_enc != total_enc || ok_dec != total_dec || iter_ok != iter_n) bad++;
    pstr(bad ? "FAIL\n" : "PASS\n");
    return bad ? 1 : 0;
}
